namespace IngestaDeDatos.Api.Services;

// SQL parametrizado de DDCP. Se conserva el texto y el orden transaccional.
internal static class DdcpSql
{
    public const string ConsultarRegistros = "SELECT ID_ENTIDAD IdEntidad, NOMBRE_ENTIDAD NombreEntidad, NUM_DIS_DECOMISADOS Dispositivos, PERSONAS_P_DISPOSICION Personas, REVISION Revision, HABILITADO Habilitado, PERIODO Periodo FROM dbo.DISPOSITIVOS_DECOMISADOS WHERE YEAR(PERIODO) = @anio AND (@mes IS NULL OR MONTH(PERIODO) = @mes) AND (@entidad IS NULL OR ID_ENTIDAD = @entidad);";

    public const string ConsultarEntidades = "SELECT ID_ENTIDAD IdEntidad, NOMBRE_ENTIDAD NombreEntidad, NOMBRE_CORTO NombreCorto FROM dbo.CAT_ENTIDAD WHERE HABILITADO = 1 AND (@id IS NULL OR ID_ENTIDAD = @id) ORDER BY ID_ENTIDAD;";

    public const string CrearVistaPrevia = "INSERT dbo.DDCP_CARGA(ID_CARGA, ID_USUARIO, PERIODO, ESTADO, NOMBRE_ARCHIVO, ARCHIVO, FILAS_JSON) VALUES (@id, @usuario, @periodo, 'PREVIA', @nombre, @bytes, @json);";

    public const string ObtenerCargaParaConfirmar = "SELECT ID_CARGA IdCarga, ID_USUARIO IdUsuario, PERIODO Periodo, ESTADO Estado, FILAS_JSON FilasJson FROM dbo.DDCP_CARGA WITH (UPDLOCK, HOLDLOCK) WHERE ID_CARGA = @id;";

    public const string EntidadHabilitada = "SELECT CASE WHEN EXISTS (SELECT 1 FROM dbo.CAT_ENTIDAD WHERE ID_ENTIDAD = @entidad AND HABILITADO = 1) THEN 1 ELSE 0 END;";

    public const string ObtenerRegistroParaConfirmar = "SELECT NUM_DIS_DECOMISADOS Dispositivos, PERSONAS_P_DISPOSICION Personas, REVISION Revision, HABILITADO Habilitado FROM dbo.DISPOSITIVOS_DECOMISADOS WITH (UPDLOCK, HOLDLOCK) WHERE ID_ENTIDAD = @entidad AND PERIODO = @periodo;";

    public const string InsertarRegistro = "INSERT dbo.DISPOSITIVOS_DECOMISADOS(ID_DISPOSITIVO_DECOMISADO, NOMBRE_ENTIDAD, NUM_DIS_DECOMISADOS, PERSONAS_P_DISPOSICION, FECHA_CREACION, HABILITADO, ID_ENTIDAD, PERIODO, FECHA_INGESTA, REVISION) VALUES (NEXT VALUE FOR dbo.SEQ_DECOMISO, @nombre, @dispositivos, @personas, GETDATE(), 1, @entidad, @periodo, SYSUTCDATETIME(), 1);";

    public const string GuardarHistorico = "INSERT dbo.DDCP_HISTORICO(ID_DISPOSITIVO_DECOMISADO, ID_ENTIDAD, NOMBRE_ENTIDAD, PERIODO, NUM_DIS_DECOMISADOS, PERSONAS_P_DISPOSICION, REVISION, HABILITADO, FECHA_CREACION, FECHA_MODIFICACION, FECHA_INGESTA, ID_CARGA, ID_USUARIO) SELECT ID_DISPOSITIVO_DECOMISADO, ID_ENTIDAD, NOMBRE_ENTIDAD, PERIODO, NUM_DIS_DECOMISADOS, PERSONAS_P_DISPOSICION, REVISION, HABILITADO, FECHA_CREACION, FECHA_MODIFICACION, FECHA_INGESTA, @id, @usuario FROM dbo.DISPOSITIVOS_DECOMISADOS WHERE ID_ENTIDAD = @entidad AND PERIODO = @periodo;";

    public const string ActualizarRegistro = "UPDATE dbo.DISPOSITIVOS_DECOMISADOS SET NUM_DIS_DECOMISADOS = @dispositivos, PERSONAS_P_DISPOSICION = @personas, FECHA_MODIFICACION = GETDATE(), FECHA_INGESTA = SYSUTCDATETIME(), REVISION = REVISION + 1, HABILITADO = 1 WHERE ID_ENTIDAD = @entidad AND PERIODO = @periodo;";

    public const string ConfirmarCarga = "UPDATE dbo.DDCP_CARGA SET ESTADO = 'CONFIRMADA', FECHA_CONFIRMACION = SYSUTCDATETIME() WHERE ID_CARGA = @id;";

    public const string CancelarCarga = "UPDATE dbo.DDCP_CARGA SET ESTADO = 'CANCELADA' WHERE ID_CARGA = @id AND ID_USUARIO = @usuario AND ESTADO = 'PREVIA';";

}
